/* 자동 생성 — tools/build_toefl.py. 직접 고치지 마세요. */
(window.TS_DATA = window.TS_DATA || {}).tf_s_repeat = [{"id":"sr-001","level":1,"topic":"캠퍼스 투어","voice":"female","sentences":["Welcome to our campus.","This is the main library.","It is open until ten every night.","The student center is just across the street.","You can buy food and coffee there all day long.","Next, we will walk to the science building near the lake.","Please stay with the group and ask me questions at any time during the tour."],"translations":["우리 캠퍼스에 오신 것을 환영합니다.","여기가 중앙 도서관입니다.","매일 밤 10시까지 문을 엽니다.","학생회관은 바로 길 건너편에 있습니다.","그곳에서는 하루 종일 음식과 커피를 살 수 있습니다.","다음으로 호수 근처에 있는 과학관으로 걸어가겠습니다.","투어 동안 일행과 함께 다니시고, 궁금한 것은 언제든지 물어보세요."]},{"id":"sr-002","level":1,"topic":"도서관 안내","voice":"male","sentences":["Hello, and welcome, everyone.","This is our quiet study room.","Please keep your phones on silent here.","You can borrow up to ten books.","Show your student card at the front desk.","If you need help finding a book, just ask our staff.","Books are due in two weeks, but you can renew them online at home."],"translations":["안녕하세요, 여러분 환영합니다.","여기는 조용한 열람실입니다.","이곳에서는 휴대폰을 무음으로 해 주세요.","책은 10권까지 빌릴 수 있습니다.","안내 데스크에서 학생증을 보여 주세요.","책을 찾는 데 도움이 필요하면 직원에게 물어보세요.","책은 2주 뒤에 반납해야 하지만, 집에서 온라인으로 연장할 수 있습니다."]},{"id":"sr-003","level":1,"topic":"학생 식당 안내","voice":"female","sentences":["Good morning, and welcome.","This is the student cafeteria.","Breakfast is served from seven to ten.","Take a tray and a plate from this table.","Hot food is on the left, and salads are on the right.","You can pay with cash, a credit card, or your student card.","Please put your tray on the cart by the door when you finish eating."],"translations":["좋은 아침입니다, 환영합니다.","여기는 학생 식당입니다.","아침 식사는 7시부터 10시까지 제공됩니다.","이 테이블에서 쟁반과 접시를 가져가세요.","따뜻한 음식은 왼쪽에, 샐러드는 오른쪽에 있습니다.","현금, 신용카드, 또는 학생증으로 계산할 수 있습니다.","식사를 마치면 문 옆 카트에 쟁반을 올려 주세요."]},{"id":"sr-004","level":1,"topic":"체육관 안내","voice":"male","sentences":["Welcome to the gym.","The pool is downstairs.","Lockers are next to the showers.","Bring your own lock and a towel.","The weight room opens at six in the morning.","Students can use the gym for free with their ID card.","If you want to join a yoga or dance class, sign up at the front desk."],"translations":["체육관에 오신 것을 환영합니다.","수영장은 아래층에 있습니다.","사물함은 샤워실 옆에 있습니다.","자물쇠와 수건은 직접 가져오세요.","웨이트장은 아침 6시에 문을 엽니다.","학생들은 학생증으로 체육관을 무료로 이용할 수 있습니다.","요가나 댄스 수업에 참여하고 싶으면 안내 데스크에서 신청하세요."]},{"id":"sr-005","level":1,"topic":"기숙사 안내","voice":"female","sentences":["Welcome to Oak Hall.","Your room is on the second floor.","Each room has two beds and two desks.","The kitchen and laundry room are on the first floor.","Please clean the kitchen after you cook.","Quiet hours start at eleven at night on weekdays.","If you lose your key, go to the front desk and ask for help right away."],"translations":["오크 홀에 오신 것을 환영합니다.","여러분의 방은 2층에 있습니다.","방마다 침대 두 개와 책상 두 개가 있습니다.","주방과 세탁실은 1층에 있습니다.","요리한 후에는 주방을 치워 주세요.","평일에는 밤 11시부터 조용히 해야 하는 시간입니다.","열쇠를 잃어버리면 바로 안내 데스크에 가서 도움을 요청하세요."]},{"id":"sr-006","level":1,"topic":"박물관 안내","voice":"male","sentences":["Welcome to our museum.","Please do not touch the paintings.","This room shows art from Asia.","These bowls are more than five hundred years old.","You can take photos, but please do not use a flash.","The gift shop and the cafe are at the end of the hall.","Our next tour starts at two o'clock, so feel free to come back with your friends."],"translations":["우리 박물관에 오신 것을 환영합니다.","그림을 만지지 마세요.","이 방은 아시아 미술품을 보여 줍니다.","이 그릇들은 500년이 넘었습니다.","사진은 찍어도 되지만 플래시는 사용하지 마세요.","기념품 가게와 카페는 복도 끝에 있습니다.","다음 투어는 2시에 시작하니 친구들과 함께 다시 오셔도 좋습니다."]},{"id":"sr-007","level":2,"topic":"실험실 안전 교육","voice":"female","sentences":["Let's start with safety.","Always wear your goggles in the lab.","Long hair should be tied back before you begin.","Never eat or drink anything while you are working here.","The fire extinguisher is located next to the door on your right.","If a chemical touches your skin, wash it with water for fifteen minutes.","Before you leave, make sure all the equipment is turned off and your area is clean."],"translations":["안전 수칙부터 시작하겠습니다.","실험실에서는 항상 보안경을 쓰세요.","시작하기 전에 긴 머리는 뒤로 묶어야 합니다.","이곳에서 작업하는 동안에는 절대 아무것도 먹거나 마시지 마세요.","소화기는 오른쪽 문 옆에 있습니다.","화학 물질이 피부에 닿으면 15분 동안 물로 씻어 내세요.","나가기 전에 모든 장비가 꺼져 있고 자리가 깨끗한지 확인하세요."]},{"id":"sr-008","level":2,"topic":"신입생 오리엔테이션","voice":"male","sentences":["Hi, I'm your orientation leader.","Today we'll visit the most important offices.","First, this is where you get your student ID.","The advising office helps you choose classes that match your major.","If you have trouble with your schedule, you can make an appointment online.","The health center, which is behind the library, offers free checkups for all students.","By the end of today, you should feel comfortable finding your way around campus on your own."],"translations":["안녕하세요, 저는 여러분의 오리엔테이션 리더입니다.","오늘은 가장 중요한 사무실들을 방문하겠습니다.","먼저, 이곳이 학생증을 발급받는 곳입니다.","학업 상담실은 전공에 맞는 수업을 고르도록 도와줍니다.","시간표에 문제가 있으면 온라인으로 상담 예약을 할 수 있습니다.","도서관 뒤에 있는 보건소에서는 모든 학생에게 무료 건강 검진을 제공합니다.","오늘이 끝날 때쯤이면 혼자서도 캠퍼스를 편하게 찾아다닐 수 있을 거예요."]},{"id":"sr-009","level":2,"topic":"대학 서점","voice":"female","sentences":["This is the campus bookstore.","Textbooks are on the second floor.","They're sorted by department and course number.","Used books are cheaper, but they sell out quickly.","You can also rent textbooks and return them after final exams.","If you drop a class, you can return the book within two weeks.","Just remember to keep your receipt, because we can't give you a full refund without it."],"translations":["여기는 캠퍼스 서점입니다.","교재는 2층에 있습니다.","학과와 과목 번호별로 정리되어 있습니다.","중고 책은 더 싸지만 빨리 팔립니다.","교재를 대여했다가 기말고사 후에 반납할 수도 있습니다.","수강을 취소하면 2주 안에 책을 반품할 수 있습니다.","영수증 없이는 전액 환불이 안 되니 영수증을 꼭 보관하세요."]},{"id":"sr-010","level":2,"topic":"캠퍼스 셔틀버스 안내","voice":"male","sentences":["Let's talk about getting around.","The campus shuttle is completely free.","It runs every fifteen minutes on weekdays.","The main stop is right in front of the student union.","On weekends, the buses come less often, so check the schedule first.","You can see where each bus is in real time by using the campus app.","If you miss the last bus at midnight, you can call the safe ride service to get home."],"translations":["캠퍼스 이동 방법에 대해 이야기해 봅시다.","캠퍼스 셔틀은 완전히 무료입니다.","평일에는 15분마다 운행합니다.","주 정류장은 학생회관 바로 앞에 있습니다.","주말에는 버스가 덜 자주 오니 먼저 시간표를 확인하세요.","캠퍼스 앱을 사용하면 각 버스의 위치를 실시간으로 볼 수 있습니다.","자정 막차를 놓치면 안심 귀가 서비스에 전화해서 집에 갈 수 있습니다."]},{"id":"sr-011","level":2,"topic":"대학 온실 견학","voice":"female","sentences":["This is the university greenhouse.","It was built about fifty years ago.","Students grow plants here for their research projects.","The temperature and humidity are controlled by a computer system.","This section holds desert plants that need very little water.","Over there, you'll see tropical flowers that were brought from South America.","Visitors are welcome on Friday afternoons, but please don't pick or touch any of the plants without permission."],"translations":["여기는 대학 온실입니다.","약 50년 전에 지어졌습니다.","학생들은 연구 과제를 위해 이곳에서 식물을 기릅니다.","온도와 습도는 컴퓨터 시스템으로 조절됩니다.","이 구역에는 물이 거의 필요 없는 사막 식물이 있습니다.","저쪽에는 남아메리카에서 들여온 열대 꽃들이 보일 겁니다.","금요일 오후에는 방문객을 환영하지만, 허락 없이 식물을 꺾거나 만지지 마세요."]},{"id":"sr-012","level":2,"topic":"취업 지원 센터","voice":"male","sentences":["Welcome to the career center.","We help students find jobs and internships.","You can get your resume checked for free.","Our advisors can also help you practice for interviews.","Every spring, we hold a job fair with more than a hundred companies.","It's a good idea to visit us early, even if you're only in your first year.","Students who start planning early usually have more options when they graduate and start looking for work."],"translations":["취업 지원 센터에 오신 것을 환영합니다.","저희는 학생들이 일자리와 인턴십을 찾도록 돕습니다.","이력서를 무료로 점검받을 수 있습니다.","상담사들이 면접 연습도 도와드릴 수 있습니다.","매년 봄에는 100개가 넘는 기업이 참여하는 채용 박람회를 엽니다.","1학년이라도 일찍 방문하는 것이 좋습니다.","일찍 준비를 시작하는 학생들이 보통 졸업하고 일자리를 찾을 때 선택지가 더 많습니다."]},{"id":"sr-013","level":3,"topic":"심리학 연구실 소개","voice":"female","sentences":["Welcome to the cognition lab.","This is where we run our memory experiments.","Participants sit in these booths and complete tasks on a computer.","Each session is recorded, so we can review the data later if needed.","All personal information is stored on a secure server that only researchers can access.","If you'd like to volunteer as a participant, you'll receive course credit or a small payment.","Before any study begins, participants are asked to sign a consent form explaining exactly how their data will be used."],"translations":["인지 연구실에 오신 것을 환영합니다.","이곳에서 기억 실험을 진행합니다.","참가자들은 이 부스에 앉아 컴퓨터로 과제를 수행합니다.","각 세션은 녹화되므로 필요하면 나중에 데이터를 다시 검토할 수 있습니다.","모든 개인 정보는 연구자만 접근할 수 있는 보안 서버에 저장됩니다.","참가자로 자원하시면 학점이나 소정의 사례비를 받게 됩니다.","연구가 시작되기 전에 참가자들은 자신의 데이터가 정확히 어떻게 사용될지 설명하는 동의서에 서명하게 됩니다."]},{"id":"sr-014","level":3,"topic":"미술관 가이드","voice":"male","sentences":["Let's move into the next gallery.","These paintings were donated by a former student.","Most of them date from the early twentieth century.","Notice how the artist uses light to draw your eye toward the center.","Critics ignored her work at first, but today she's considered a pioneer of modern art.","This particular piece was damaged in a flood and carefully restored in the nineteen-nineties.","If you look closely at the corner, you can still see where the original paint was left untouched by the restorers."],"translations":["다음 전시실로 이동하겠습니다.","이 그림들은 한 졸업생이 기증했습니다.","대부분 20세기 초 작품입니다.","화가가 빛을 이용해 시선을 중앙으로 끌어들이는 방식을 보세요.","처음에 비평가들은 그녀의 작품을 무시했지만, 오늘날 그녀는 현대 미술의 선구자로 여겨집니다.","이 작품은 홍수로 손상되었다가 1990년대에 정성껏 복원되었습니다.","모서리를 자세히 보면 복원가들이 손대지 않고 남겨 둔 원래 물감 부분을 아직도 볼 수 있습니다."]},{"id":"sr-015","level":3,"topic":"수영장 안전 안내","voice":"female","sentences":["Please listen carefully before swimming.","Showers are required before entering the water.","Lifeguards are on duty whenever the pool is open.","The deep end is marked with a red line along the edge.","Swimmers who aren't confident should stay in the lanes closest to the wall.","Running on the deck is strictly prohibited, since the tiles get extremely slippery when wet.","If you hear three short whistles, leave the water immediately and gather near the main entrance for instructions."],"translations":["수영하기 전에 잘 들어 주세요.","물에 들어가기 전에 반드시 샤워해야 합니다.","수영장이 열려 있는 동안에는 항상 안전 요원이 근무합니다.","깊은 쪽은 가장자리에 빨간 선으로 표시되어 있습니다.","수영에 자신이 없는 분은 벽에 가장 가까운 레인에 머물러야 합니다.","타일이 젖으면 매우 미끄러우므로 수영장 바닥에서 뛰는 것은 엄격히 금지됩니다.","짧은 호루라기 소리가 세 번 들리면 즉시 물에서 나와 정문 근처에 모여 안내를 기다리세요."]},{"id":"sr-016","level":3,"topic":"도서관 고문헌 자료실","voice":"male","sentences":["Welcome to special collections.","Bags and coats must stay in the lockers.","Only pencils are allowed, since ink can damage the documents.","Many of these manuscripts are over three hundred years old and extremely fragile.","You'll need to request materials at least a day in advance through our website.","Staff will bring the items to your table, and they must remain in this room at all times.","Photography is usually allowed, but some items are still under copyright, so please check with a librarian before taking any pictures."],"translations":["특별 자료실에 오신 것을 환영합니다.","가방과 외투는 사물함에 두어야 합니다.","잉크는 문서를 손상시킬 수 있으므로 연필만 허용됩니다.","이 필사본 중 상당수는 300년이 넘었고 매우 손상되기 쉽습니다.","자료는 적어도 하루 전에 웹사이트로 신청해야 합니다.","직원이 자료를 자리로 가져다 드리며, 자료는 항상 이 방 안에 있어야 합니다.","사진 촬영은 대개 허용되지만 일부 자료는 아직 저작권이 있으니 촬영 전에 사서에게 확인하세요."]},{"id":"sr-017","level":3,"topic":"해양 연구소 견학","voice":"female","sentences":["Welcome to the marine research station.","We study ocean life along this coast.","The tanks behind me contain water pumped directly from the bay.","That allows us to observe animals in conditions close to their natural habitat.","Right now, our team is tracking how rising water temperatures affect local shellfish.","The data we collect is shared with government agencies that manage fishing in the region.","Students interested in joining a summer project should contact the station director before the application deadline in March."],"translations":["해양 연구소에 오신 것을 환영합니다.","저희는 이 해안의 해양 생물을 연구합니다.","제 뒤에 있는 수조에는 만에서 바로 끌어온 바닷물이 들어 있습니다.","덕분에 자연 서식지와 비슷한 환경에서 동물을 관찰할 수 있습니다.","지금 저희 팀은 수온 상승이 이 지역 조개류에 어떤 영향을 주는지 추적하고 있습니다.","수집한 데이터는 이 지역의 어업을 관리하는 정부 기관과 공유됩니다.","여름 프로젝트에 참여하고 싶은 학생은 3월 지원 마감 전에 연구소장에게 연락해야 합니다."]},{"id":"sr-018","level":3,"topic":"오리엔테이션 - 학사 규정","voice":"male","sentences":["Now let's talk about academics.","Full-time students take at least twelve credits.","You can add or drop classes during the first week.","Every student is assigned an academic advisor based on their intended major.","After the first week, dropping a course will appear as a withdrawal on your transcript.","It's worth meeting your advisor early, because some required courses are only offered once a year.","Keep in mind that academic dishonesty, including copying a classmate's work, can lead to serious consequences such as suspension."],"translations":["이제 학업에 관해 이야기해 봅시다.","전일제 학생은 최소 12학점을 수강합니다.","첫 주 동안에는 수업을 추가하거나 취소할 수 있습니다.","모든 학생에게는 희망 전공에 따라 지도 교수가 배정됩니다.","첫 주가 지나면 수강 취소는 성적표에 '수강 철회'로 표시됩니다.","일부 필수 과목은 1년에 한 번만 개설되므로 지도 교수를 일찍 만나 두는 것이 좋습니다.","친구의 과제를 베끼는 것을 포함한 학업 부정행위는 정학 같은 심각한 결과로 이어질 수 있다는 점을 명심하세요."]},{"id":"sr-019","level":4,"topic":"화학 실험실 안전 브리핑","voice":"male","sentences":["A few ground rules first.","Goggles stay on for the entire session.","Any spill, however minor, must be reported to the instructor immediately.","Waste containers are labeled by chemical type, so never combine them without checking.","The fume hoods should be used whenever you're working with volatile or strong-smelling substances.","In the unlikely event of a fire, shut off the gas supply and evacuate through the nearest marked exit.","Failure to follow these procedures not only puts you at risk, but may also result in your being removed from the course entirely."],"translations":["먼저 기본 규칙 몇 가지입니다.","보안경은 실습 내내 쓰고 있어야 합니다.","쏟은 것이 있으면 아무리 적어도 즉시 강사에게 알려야 합니다.","폐기물 용기는 화학 물질 종류별로 표시되어 있으니 확인 없이 절대 섞지 마세요.","휘발성이 있거나 냄새가 강한 물질을 다룰 때는 반드시 흄 후드를 사용해야 합니다.","만일 화재가 발생하면 가스 공급을 차단하고 가장 가까운 표시된 비상구로 대피하세요.","이 절차를 따르지 않으면 본인이 위험해질 뿐 아니라 수강 자체가 취소될 수도 있습니다."]},{"id":"sr-020","level":4,"topic":"고고학 박물관 - 고대 교역","voice":"female","sentences":["This gallery focuses on early trade.","These coins were found along ancient trade routes.","Their wide distribution suggests that commerce extended much farther than once believed.","Chemical analysis of the residue inside these jars revealed traces of olive oil and wine.","The jars themselves were recovered from a shipwreck discovered off the coast about thirty years ago.","What makes these findings remarkable is that they challenge the long-held assumption that these communities were largely isolated.","Researchers are still debating whether the goods were traded directly or passed along through a chain of intermediaries over several generations."],"translations":["이 전시실은 초기 교역을 다룹니다.","이 동전들은 고대 교역로를 따라 발견되었습니다.","넓게 분포되어 있다는 점은 상업이 한때 생각했던 것보다 훨씬 멀리까지 뻗어 있었음을 시사합니다.","이 항아리 안에 남은 잔여물을 화학 분석한 결과 올리브유와 포도주의 흔적이 드러났습니다.","항아리 자체는 약 30년 전 연안에서 발견된 난파선에서 인양되었습니다.","이 발견이 주목할 만한 이유는 이 공동체들이 대체로 고립되어 있었다는 오랜 가정에 의문을 제기하기 때문입니다.","연구자들은 이 물품들이 직접 거래되었는지, 아니면 여러 세대에 걸쳐 중개인들을 거쳐 전달되었는지를 아직도 논쟁하고 있습니다."]},{"id":"sr-021","level":4,"topic":"천문대 견학","voice":"male","sentences":["Welcome to the campus observatory.","Our main telescope is over sixty years old.","Despite its age, it remains remarkably precise.","The dome rotates so that the telescope can follow objects across the night sky.","Unfortunately, light pollution from the city has become a serious obstacle for our observations.","As a result, much of our research now relies on data collected remotely by telescopes in the desert.","Nevertheless, public viewing nights remain popular, and on clear evenings we frequently welcome more than two hundred visitors from the surrounding community."],"translations":["캠퍼스 천문대에 오신 것을 환영합니다.","저희 주 망원경은 60년이 넘었습니다.","오래되었는데도 여전히 놀랄 만큼 정밀합니다.","돔이 회전하기 때문에 망원경이 밤하늘을 가로지르는 천체를 따라갈 수 있습니다.","안타깝게도 도시의 빛 공해가 관측에 큰 걸림돌이 되었습니다.","그 결과 이제 연구의 상당 부분은 사막에 있는 망원경들이 원격으로 수집한 데이터에 의존합니다.","그럼에도 일반인 관측의 밤은 여전히 인기가 많아서, 맑은 저녁에는 인근 지역에서 200명이 넘는 방문객이 찾아오는 일이 흔합니다."]},{"id":"sr-022","level":4,"topic":"신경과학 연구실 신입 안내","voice":"female","sentences":["Welcome to the lab, everyone.","Let me explain how we handle data.","Raw data files must never be edited or overwritten directly.","Instead, make a copy and document every change in the shared log.","This ensures that anyone can reconstruct exactly how a particular result was obtained.","Reproducibility has become a major concern across the sciences, and funding agencies now expect detailed records.","If you're ever uncertain about whether a procedure complies with our protocols, it's far better to ask than to make assumptions."],"translations":["여러분, 연구실에 오신 것을 환영합니다.","데이터를 어떻게 다루는지 설명하겠습니다.","원본 데이터 파일은 절대 직접 편집하거나 덮어쓰면 안 됩니다.","대신 사본을 만들고 모든 변경 사항을 공유 기록부에 적으세요.","그래야 누구든 특정 결과가 정확히 어떻게 나왔는지 재구성할 수 있습니다.","재현 가능성은 과학 전반의 주요 관심사가 되었고, 연구비 지원 기관들은 이제 상세한 기록을 요구합니다.","어떤 절차가 우리 규정에 맞는지 확실하지 않을 때는 짐작하기보다 물어보는 편이 훨씬 낫습니다."]},{"id":"sr-023","level":4,"topic":"친환경 건물 투어","voice":"male","sentences":["This building is entirely solar-powered.","It opened three years ago as a pilot project.","The panels on the roof generate more energy than the building consumes.","Surplus electricity is fed back into the campus grid during peak hours.","Rainwater collected from the roof is filtered and reused for irrigation and flushing toilets.","Although construction costs were considerably higher, the university expects to recover the investment within roughly fifteen years.","If the pilot proves successful, administrators hope to apply similar design principles to every new building on campus over the coming decade."],"translations":["이 건물은 전부 태양광으로 전력을 얻습니다.","3년 전에 시범 사업으로 문을 열었습니다.","지붕의 패널은 건물이 소비하는 것보다 더 많은 에너지를 생산합니다.","남는 전기는 사용량이 많은 시간대에 캠퍼스 전력망으로 다시 보내집니다.","지붕에서 모은 빗물은 걸러서 조경용 물과 화장실 물로 재사용합니다.","건설 비용은 상당히 더 들었지만, 대학은 약 15년 안에 투자금을 회수할 것으로 예상합니다.","시범 사업이 성공하면 관리자들은 앞으로 10년 동안 캠퍼스의 모든 신축 건물에 비슷한 설계 원칙을 적용하기를 바랍니다."]},{"id":"sr-024","level":4,"topic":"도서관 연구 지원 워크숍","voice":"female","sentences":["Let's talk about finding sources.","Our databases cover nearly every academic discipline.","Most journal articles can be downloaded in full through the library website.","If an article isn't available, you can request it through interlibrary loan at no cost.","Be aware, though, that such requests can occasionally take up to a week to be processed.","Research librarians offer one-on-one consultations, which are particularly useful when you're just beginning a thesis.","Many students underestimate how much time a thorough literature review requires, so I'd strongly encourage you to begin well before your deadlines."],"translations":["자료를 찾는 방법에 대해 이야기해 봅시다.","저희 데이터베이스는 거의 모든 학문 분야를 다룹니다.","대부분의 학술지 논문은 도서관 웹사이트에서 전문을 내려받을 수 있습니다.","논문을 구할 수 없으면 상호대차 서비스로 무료로 신청할 수 있습니다.","다만 그런 신청은 처리되는 데 가끔 일주일까지 걸릴 수 있다는 점을 알아 두세요.","연구 전담 사서들이 일대일 상담을 해 주는데, 이제 막 학위 논문을 시작할 때 특히 유용합니다.","많은 학생이 철저한 선행 연구 검토에 드는 시간을 과소평가하므로, 마감일보다 훨씬 전에 시작하기를 강력히 권합니다."]},{"id":"sr-025","level":5,"topic":"생물 안전 교육","voice":"male","sentences":["Biosafety protocols here are non-negotiable.","Every researcher must complete certification before handling live cultures.","Lab coats are to remain inside the containment area at all times.","Should you suspect any exposure, however unlikely it may seem, notify your supervisor without delay.","Decontamination procedures are not merely a formality; they are what stand between a routine experiment and a genuine hazard.","Only after the biological safety cabinet has run for a full ten minutes may you begin transferring any samples.","Bear in mind that the institution's accreditation, and consequently its eligibility for federal funding, depends on our strict and consistent adherence to these standards."],"translations":["이곳의 생물 안전 규정은 협상의 여지가 없습니다.","모든 연구자는 살아 있는 배양체를 다루기 전에 인증 과정을 마쳐야 합니다.","실험복은 항상 격리 구역 안에 두어야 합니다.","노출이 의심되면, 그럴 가능성이 아무리 낮아 보여도 지체 없이 책임자에게 알리세요.","오염 제거 절차는 단순한 형식이 아니라, 일상적인 실험과 실제 위험을 가르는 경계입니다.","생물 안전 작업대를 꼬박 10분간 가동한 뒤에야 시료를 옮기기 시작할 수 있습니다.","기관의 인증, 그리고 그에 따른 연방 연구비 지원 자격은 우리가 이 기준을 엄격하고 일관되게 지키는 데 달려 있다는 점을 명심하세요."]},{"id":"sr-026","level":5,"topic":"미술관 큐레이터 해설","voice":"female","sentences":["This exhibition took years to assemble.","Several of these works have never been shown publicly.","Rarely does a collection of this scope travel outside its home institution.","The curators deliberately arranged the pieces thematically rather than chronologically to provoke unexpected comparisons.","Notice how the earlier landscapes, with their meticulous detail, stand in stark contrast to the looser brushwork nearby.","It was precisely this shift toward abstraction that divided critics, some of whom dismissed the later work as unfinished.","Whether one regards the change as a decline or a liberation largely depends on what one believes the purpose of painting to be."],"translations":["이 전시는 준비하는 데 몇 년이 걸렸습니다.","이 작품들 중 몇 점은 한 번도 대중에게 공개된 적이 없습니다.","이 정도 규모의 소장품이 소속 기관 밖으로 나오는 일은 드뭅니다.","큐레이터들은 예상치 못한 비교를 끌어내려고 작품을 시대순이 아니라 주제별로 일부러 배치했습니다.","세밀한 묘사가 돋보이는 초기 풍경화가 바로 옆의 느슨한 붓질과 얼마나 뚜렷하게 대비되는지 보세요.","비평가들을 갈라놓은 것은 바로 이 추상으로의 전환이었고, 그중 일부는 후기 작품을 미완성이라며 깎아내렸습니다.","이 변화를 쇠퇴로 보느냐 해방으로 보느냐는 대체로 그림의 목적이 무엇이라고 믿느냐에 달려 있습니다."]},{"id":"sr-027","level":5,"topic":"대학원 오리엔테이션 - 연구 윤리","voice":"male","sentences":["Let's turn to research integrity.","Plagiarism extends well beyond copying someone's exact words.","Paraphrasing an idea without attribution is treated with equal seriousness.","Likewise, selectively reporting only the results that support your hypothesis constitutes a form of misconduct.","Graduate students often find themselves under considerable pressure to publish, which can make such shortcuts tempting.","Nonetheless, the consequences of fabrication, once discovered, tend to follow a researcher for the remainder of their career.","What ultimately sustains public trust in scholarship is not the occasional groundbreaking discovery, but the quiet, cumulative reliability of ordinary research."],"translations":["이제 연구 윤리로 넘어가겠습니다.","표절은 남의 말을 그대로 베끼는 것에 그치지 않습니다.","출처를 밝히지 않고 아이디어를 바꿔 쓰는 것도 똑같이 심각하게 다뤄집니다.","마찬가지로 가설을 뒷받침하는 결과만 골라서 보고하는 것도 일종의 연구 부정입니다.","대학원생은 논문 발표에 대한 상당한 압박을 받는 경우가 많아서 그런 지름길이 솔깃하게 느껴질 수 있습니다.","그렇지만 조작은 한번 드러나면 그 결과가 연구자의 남은 경력 내내 따라다니는 경향이 있습니다.","학문에 대한 대중의 신뢰를 궁극적으로 지탱하는 것은 가끔 나오는 획기적 발견이 아니라, 평범한 연구가 조용히 쌓아 가는 신뢰성입니다."]},{"id":"sr-028","level":5,"topic":"지질학 야외 실습 브리핑","voice":"female","sentences":["Tomorrow's field trip starts at dawn.","Sturdy boots and layered clothing are essential.","Weather conditions along the ridge can change dramatically within a matter of minutes.","The rock formations we'll examine were exposed when an ancient lake bed gradually eroded away.","Pay particular attention to the alternating layers, as they record cycles of flooding and drought spanning thousands of years.","Under no circumstances should anyone wander away from the group, since mobile reception in the canyon is virtually nonexistent.","Samples may be collected only from designated sites, given that the surrounding land is protected and any unauthorized removal could jeopardize our permit."],"translations":["내일 현장 답사는 새벽에 시작합니다.","튼튼한 등산화와 여러 겹의 옷은 필수입니다.","능선의 날씨는 불과 몇 분 만에 극적으로 바뀔 수 있습니다.","우리가 살펴볼 암석층은 고대 호수 바닥이 서서히 침식되면서 드러난 것입니다.","번갈아 나타나는 지층에 특히 주의를 기울이세요. 수천 년에 걸친 홍수와 가뭄의 주기가 기록되어 있습니다.","협곡에서는 휴대폰이 거의 터지지 않으므로 어떤 경우에도 일행에서 떨어져 돌아다니면 안 됩니다.","주변 땅은 보호 구역이고 허가 없이 반출하면 우리 허가가 위태로워질 수 있으므로, 시료는 지정된 장소에서만 채취할 수 있습니다."]},{"id":"sr-029","level":5,"topic":"대학 역사 투어","voice":"male","sentences":["This hall predates the university itself.","It originally served as a military hospital.","Following the war, the building stood abandoned for nearly two decades.","Its eventual conversion into lecture halls was financed largely by donations from local residents.","Had those residents not intervened, the structure would almost certainly have been demolished to make room for housing.","The stained glass above the entrance, commissioned during the renovation, commemorates the nurses who worked here during the conflict.","What visitors frequently overlook, however, are the faint inscriptions on the lower walls, carved by patients whose names were otherwise lost to history."],"translations":["이 건물은 대학보다 먼저 세워졌습니다.","원래는 군 병원으로 쓰였습니다.","전쟁이 끝난 뒤 건물은 거의 20년 동안 버려져 있었습니다.","결국 강의동으로 바뀌었는데, 그 비용은 주로 지역 주민들의 기부로 마련되었습니다.","그 주민들이 나서지 않았다면 이 건물은 주택을 짓기 위해 거의 확실히 철거되었을 것입니다.","개보수 때 의뢰된 입구 위의 스테인드글라스는 전쟁 중 이곳에서 일한 간호사들을 기립니다.","하지만 방문객들이 흔히 놓치는 것은 아래쪽 벽의 희미한 글귀인데, 그렇지 않았다면 이름이 역사 속에 사라졌을 환자들이 새긴 것입니다."]},{"id":"sr-030","level":5,"topic":"기후 모델링 연구소","voice":"female","sentences":["This is our climate modeling facility.","These servers run simulations around the clock.","A single model can take several weeks to complete, even on this hardware.","Each simulation incorporates millions of variables, from ocean currents to the reflectivity of polar ice.","Inevitably, some uncertainty persists, which is why we compare our projections against those produced by other institutions.","Where the models converge, we can speak with considerable confidence; where they diverge, further investigation is clearly warranted.","It is this ongoing process of comparison and refinement, rather than any single prediction, that ultimately gives climate science its credibility."],"translations":["이곳은 저희 기후 모델링 시설입니다.","이 서버들은 24시간 내내 시뮬레이션을 돌립니다.","이런 장비로도 모델 하나를 끝내는 데 몇 주가 걸릴 수 있습니다.","각 시뮬레이션에는 해류부터 극지방 얼음의 반사율까지 수백만 개의 변수가 들어갑니다.","불확실성은 어쩔 수 없이 남기 때문에, 저희는 다른 기관들이 내놓은 예측과 저희 예측을 비교합니다.","모델들이 일치하는 부분에서는 상당히 자신 있게 말할 수 있고, 엇갈리는 부분은 분명히 더 조사할 필요가 있습니다.","기후 과학에 신뢰성을 부여하는 것은 어느 하나의 예측이 아니라 바로 이 끊임없는 비교와 개선의 과정입니다."]},{"id":"sr-031","level":1,"topic":"캠퍼스 우편 센터 안내","voice":"female","sentences":["This is the mail center.","Every student has a mailbox here.","Your box number is on your student card.","Large packages are kept behind the front desk.","We will send you an email when a package arrives.","Please bring your student card when you come to pick it up.","The center is open from nine to five on weekdays and closed on Sundays."],"translations":["여기가 우편 센터입니다.","모든 학생은 이곳에 우편함이 있습니다.","우편함 번호는 학생증에 적혀 있습니다.","큰 소포는 안내 데스크 뒤에 보관합니다.","소포가 도착하면 이메일을 보내 드립니다.","찾으러 오실 때는 학생증을 가져오세요.","센터는 평일 9시부터 5시까지 열고 일요일에는 쉽니다."]},{"id":"sr-032","level":1,"topic":"컴퓨터실 안내","voice":"male","sentences":["This is the computer lab.","Any student can use these computers.","Log in with your school email and password.","The printers are in the small room on the left.","Each student can print fifty pages for free every week.","Please do not eat or drink anything near the computers.","If a computer is not working, write the number on a note and tell the staff."],"translations":["여기가 컴퓨터실입니다.","학생이라면 누구나 이 컴퓨터를 쓸 수 있습니다.","학교 이메일과 비밀번호로 로그인하세요.","프린터는 왼쪽 작은 방에 있습니다.","학생마다 매주 50쪽까지 무료로 인쇄할 수 있습니다.","컴퓨터 근처에서는 아무것도 먹거나 마시지 마세요.","컴퓨터가 작동하지 않으면 번호를 메모에 적어 직원에게 알려 주세요."]},{"id":"sr-033","level":1,"topic":"학생 건강 센터 안내","voice":"female","sentences":["Welcome to the health center.","We are here to help you.","You can see a nurse without an appointment.","To see a doctor, please call us a day before.","Most visits are free for students who live on campus.","We also have free cold medicine and bandages at the front desk.","If you feel very sick at night, call the number on the back of your card."],"translations":["건강 센터에 오신 것을 환영합니다.","저희는 여러분을 돕기 위해 있습니다.","예약 없이 간호사를 만날 수 있습니다.","의사 진료를 받으려면 하루 전에 전화해 주세요.","캠퍼스에 사는 학생은 대부분의 진료가 무료입니다.","안내 데스크에는 무료 감기약과 붕대도 있습니다.","밤에 많이 아프면 학생증 뒷면에 있는 번호로 전화하세요."]},{"id":"sr-034","level":1,"topic":"캠퍼스 주차 안내","voice":"male","sentences":["Let's talk about parking.","Students need a parking pass.","You can buy one online for one semester.","Student cars must park in the blue lots only.","The green lots near the main office are for teachers and staff.","If you park in the wrong place, you will have to pay a fine.","On weekends, you can park in any lot except the one next to the hospital."],"translations":["주차에 대해 이야기해 봅시다.","학생은 주차권이 필요합니다.","온라인에서 한 학기용 주차권을 살 수 있습니다.","학생 차량은 파란색 주차장에만 주차해야 합니다.","본관 근처 초록색 주차장은 교수와 직원용입니다.","잘못된 곳에 주차하면 벌금을 내야 합니다.","주말에는 병원 옆 주차장을 빼고 어느 주차장에나 주차할 수 있습니다."]},{"id":"sr-035","level":1,"topic":"분실물 센터 안내","voice":"female","sentences":["This is the lost and found.","Did you lose something on campus?","Many people lose umbrellas and water bottles.","We keep most items here for thirty days.","Phones and wallets are kept in a locked box in the office.","To get your item back, tell us what it looks like.","You can also fill out a short form online, and we will call you if we find it."],"translations":["여기가 분실물 센터입니다.","캠퍼스에서 무언가를 잃어버리셨나요?","많은 사람이 우산과 물병을 잃어버립니다.","대부분의 물건은 이곳에 30일 동안 보관합니다.","휴대폰과 지갑은 사무실의 잠긴 상자에 보관합니다.","물건을 돌려받으려면 어떻게 생겼는지 말씀해 주세요.","온라인으로 짧은 양식을 작성하셔도 되고, 물건을 찾으면 전화해 드립니다."]},{"id":"sr-036","level":1,"topic":"미술 실습실 첫 수업","voice":"male","sentences":["Welcome to the art studio.","This is where we paint.","Brushes and paper are on the back shelf.","Please wear an apron because the paint can stain clothes.","Wash your brushes in the big sink after every class.","You can leave your unfinished work on the drying rack by the window.","The studio is also open on Saturday mornings if you want more time to practice."],"translations":["미술 실습실에 오신 것을 환영합니다.","여기가 우리가 그림을 그리는 곳입니다.","붓과 종이는 뒤쪽 선반에 있습니다.","물감이 옷에 묻을 수 있으니 앞치마를 입어 주세요.","수업이 끝날 때마다 큰 싱크대에서 붓을 씻으세요.","완성하지 못한 작품은 창가 건조대에 두어도 됩니다.","연습 시간이 더 필요하면 토요일 오전에도 실습실을 엽니다."]},{"id":"sr-037","level":2,"topic":"학생 상담 센터 소개","voice":"female","sentences":["Thanks for stopping by today.","This is the student counseling center.","Our services are free and completely private.","Many students come here when they feel stressed about classes.","You can book a one-hour meeting with a counselor on our website.","We also run small group sessions on topics like sleep and time management.","If you are worried about a friend, you are welcome to come in and talk with us as well."],"translations":["오늘 들러 주셔서 감사합니다.","여기는 학생 상담 센터입니다.","저희 서비스는 무료이며 비밀이 철저히 지켜집니다.","많은 학생이 수업 때문에 스트레스를 받을 때 이곳을 찾습니다.","웹사이트에서 상담사와 한 시간 상담을 예약할 수 있습니다.","수면과 시간 관리 같은 주제로 소규모 그룹 모임도 운영합니다.","친구가 걱정된다면 그 경우에도 언제든 오셔서 저희와 이야기하셔도 됩니다."]},{"id":"sr-038","level":2,"topic":"글쓰기 센터 안내","voice":"male","sentences":["Welcome to the writing center.","Our tutors are experienced graduate students.","They can help with essays, reports, and applications.","Each session lasts thirty minutes, so bring specific questions.","Please remember that tutors will not correct every mistake for you.","Instead, they will show you patterns in your writing so you can improve on your own.","Appointments fill up quickly before final exams, so try to book at least a week in advance."],"translations":["글쓰기 센터에 오신 것을 환영합니다.","저희 튜터는 경험 많은 대학원생입니다.","에세이, 보고서, 지원서를 도와드릴 수 있습니다.","한 번의 상담은 30분이므로 구체적인 질문을 가져오세요.","튜터가 모든 실수를 대신 고쳐 주지는 않는다는 점을 기억하세요.","대신 글에서 반복되는 패턴을 보여 주어 스스로 나아질 수 있게 돕습니다.","기말고사 전에는 예약이 빨리 차니 적어도 일주일 전에 예약하도록 하세요."]},{"id":"sr-039","level":2,"topic":"음악관 연습실 안내","voice":"female","sentences":["This floor has practice rooms.","Each room has a piano and a music stand.","Music majors can reserve rooms up to two weeks ahead.","Other students may use any empty room after six in the evening.","The rooms are soundproof, but please keep the doors closed while you play.","Drums and other loud instruments are allowed only in the large room at the end of the hall.","If you notice that a piano is out of tune, please report it at the front office so we can fix it."],"translations":["이 층에는 연습실이 있습니다.","각 방에는 피아노와 보면대가 있습니다.","음악 전공생은 최대 2주 전부터 미리 방을 예약할 수 있습니다.","다른 학생은 저녁 6시 이후 비어 있는 방을 아무 곳이나 쓸 수 있습니다.","방은 방음이 되지만 연주하는 동안에는 문을 닫아 주세요.","드럼과 다른 큰 소리의 악기는 복도 끝 큰 방에서만 허용됩니다.","피아노 음이 맞지 않으면 고칠 수 있도록 앞쪽 사무실에 알려 주세요."]},{"id":"sr-040","level":2,"topic":"대학 농장 견학","voice":"male","sentences":["This is our university farm.","Students run it with help from two staff members.","We grow vegetables for the campus dining halls.","In the spring, we plant tomatoes, beans, and several kinds of lettuce.","The chickens over there give us about two hundred eggs every week.","Volunteers are always welcome, and you do not need any farming experience to join.","Just make sure to wear closed shoes and bring a hat, because there is very little shade in the fields."],"translations":["여기가 우리 대학 농장입니다.","학생들이 직원 두 명의 도움을 받아 운영합니다.","캠퍼스 식당에 쓸 채소를 기릅니다.","봄에는 토마토, 콩, 여러 종류의 상추를 심습니다.","저기 있는 닭들이 매주 약 200개의 달걀을 줍니다.","자원봉사자는 언제나 환영이며 참여하는 데 농사 경험은 필요 없습니다.","밭에는 그늘이 거의 없으니 앞이 막힌 신발을 신고 모자를 꼭 챙겨 오세요."]},{"id":"sr-041","level":2,"topic":"동아리 박람회 안내","voice":"female","sentences":["Welcome to the club fair.","There are over eighty clubs here today.","Sports clubs are set up near the main entrance.","Music, art, and theater groups are in the center of the hall.","You can write your name on as many sign-up sheets as you like.","Most clubs will send you information about their first meeting by email next week.","Before you leave, stop by the information table to pick up a free map and a list of all the clubs."],"translations":["동아리 박람회에 오신 것을 환영합니다.","오늘 이곳에는 80개가 넘는 동아리가 나와 있습니다.","운동 동아리는 정문 근처에 자리하고 있습니다.","음악, 미술, 연극 모임은 홀 가운데에 있습니다.","원하는 만큼 여러 가입 명단에 이름을 적을 수 있습니다.","대부분의 동아리가 다음 주에 첫 모임 정보를 이메일로 보내 줄 것입니다.","떠나기 전에 안내 테이블에 들러 무료 지도와 전체 동아리 목록을 받아 가세요."]},{"id":"sr-042","level":2,"topic":"교환학생 환영 모임","voice":"male","sentences":["Hello, and welcome, exchange students.","We're happy to have you here.","This semester we have students from fifteen countries.","Each of you will be matched with a local student partner.","Your partner can help you open a bank account and find your classes.","We also plan a weekend trip to the mountains at the end of this month.","If you have any questions about your visa or housing, our office in the international center is open every afternoon."],"translations":["안녕하세요, 교환학생 여러분 환영합니다.","여러분이 와 주셔서 기쁩니다.","이번 학기에는 15개국에서 온 학생들이 있습니다.","여러분은 각자 현지 학생 파트너와 짝이 됩니다.","파트너가 은행 계좌 개설과 강의실 찾기를 도와줄 수 있습니다.","이번 달 말에는 산으로 주말 여행도 계획하고 있습니다.","비자나 숙소에 관해 궁금한 점이 있으면 국제 센터에 있는 저희 사무실이 매일 오후에 열려 있습니다."]},{"id":"sr-043","level":3,"topic":"언어학 음성 연구실 소개","voice":"female","sentences":["This is the phonetics lab.","We study how people produce speech sounds.","The booth behind me blocks almost all outside noise.","Participants read short word lists while we record their voices.","The software then displays each sound as a pattern of frequencies on the screen.","By comparing these patterns, we can see how accents differ from one region to another.","Right now we're recruiting bilingual speakers for a study, and participants receive a small payment for one hour of their time."],"translations":["여기가 음성학 연구실입니다.","우리는 사람들이 말소리를 어떻게 내는지 연구합니다.","제 뒤의 부스는 바깥 소음을 거의 모두 차단합니다.","참가자들이 짧은 단어 목록을 읽는 동안 목소리를 녹음합니다.","그다음 소프트웨어가 각 소리를 화면에 주파수 패턴으로 보여 줍니다.","이 패턴들을 비교하면 지역마다 억양이 어떻게 다른지 알 수 있습니다.","지금 연구에 참여할 이중 언어 화자를 모집하고 있으며, 참가자는 한 시간에 대해 소정의 사례비를 받습니다."]},{"id":"sr-044","level":3,"topic":"로봇공학 연구실 견학","voice":"male","sentences":["Welcome to the robotics lab.","Please stay behind the yellow line.","Some of these robots move faster than you might expect.","The arm on the left is learning to sort objects by shape and color.","It improves a little each time it makes a mistake and receives feedback.","Our students design both the physical parts and the programs that control them.","Next year, the team hopes to test a small delivery robot that can carry books between the library and the dormitories."],"translations":["로봇공학 연구실에 오신 것을 환영합니다.","노란 선 뒤에 서 계세요.","이 로봇 중 일부는 생각보다 빠르게 움직입니다.","왼쪽 로봇 팔은 모양과 색으로 물건을 분류하는 법을 배우고 있습니다.","실수하고 피드백을 받을 때마다 조금씩 나아집니다.","우리 학생들은 기계 부품과 그것을 제어하는 프로그램을 모두 설계합니다.","내년에 팀은 도서관과 기숙사 사이에 책을 나를 수 있는 작은 배달 로봇을 시험해 보려고 합니다."]},{"id":"sr-045","level":3,"topic":"대학 신문사 견학","voice":"female","sentences":["This is the newsroom.","Our paper is written entirely by students.","We publish online every day and in print once a week.","Editors meet every Monday morning to decide which stories to cover.","Every article is checked by at least two people before it is published.","Reporters must confirm important facts with more than one reliable source.","You don't need to be a journalism major to join, and many of our best photographers actually study engineering."],"translations":["여기가 편집국입니다.","우리 신문은 전부 학생들이 씁니다.","온라인으로는 매일, 종이 신문으로는 일주일에 한 번 발행합니다.","편집자들은 매주 월요일 아침에 모여 어떤 기사를 다룰지 결정합니다.","모든 기사는 발행 전에 최소 두 사람이 확인합니다.","기자는 중요한 사실을 믿을 만한 출처 둘 이상으로 확인해야 합니다.","가입하는 데 언론학 전공일 필요는 없으며, 실제로 우리 최고의 사진기자 중 다수는 공학을 공부합니다."]},{"id":"sr-046","level":3,"topic":"대학 수목원 산책 안내","voice":"male","sentences":["Welcome to the university arboretum.","It covers about forty acres of land.","More than three hundred tree species grow here.","Each tree has a small metal tag showing its scientific name.","The oldest oak along this path was planted shortly after the university opened.","Biology classes use the arboretum to study how trees respond to changes in the seasons.","Please stay on the marked trails, because walking on the roots can damage trees that have taken decades to grow."],"translations":["대학 수목원에 오신 것을 환영합니다.","면적은 약 40에이커입니다.","이곳에는 300종이 넘는 나무가 자랍니다.","각 나무에는 학명이 적힌 작은 금속 표지가 달려 있습니다.","이 길을 따라 있는 가장 오래된 참나무는 대학이 문을 연 직후에 심어졌습니다.","생물학 수업에서는 나무가 계절 변화에 어떻게 반응하는지 연구하는 데 수목원을 활용합니다.","자라는 데 수십 년이 걸린 나무가 뿌리를 밟으면 다칠 수 있으니 표시된 길로만 다녀 주세요."]},{"id":"sr-047","level":3,"topic":"극장 무대 뒤 투어","voice":"female","sentences":["Let's go backstage now.","Watch your step on these stairs.","This is where the sets are built and painted.","A single production can take our crew about six weeks to prepare.","Above the stage, there are ropes and pulleys that lift scenery up and down.","The lighting team controls more than two hundred lights from a booth at the back of the theater.","Students from any department can work on the crew, and it's a great way to learn practical skills while meeting new people."],"translations":["이제 무대 뒤로 가 보겠습니다.","이 계단에서는 발밑을 조심하세요.","여기서 무대 세트를 만들고 칠합니다.","작품 하나를 준비하는 데 제작진이 약 6주가 걸리기도 합니다.","무대 위에는 배경 세트를 올리고 내리는 밧줄과 도르래가 있습니다.","조명팀은 극장 뒤쪽 부스에서 200개가 넘는 조명을 조종합니다.","어느 학과 학생이든 제작진으로 일할 수 있으며, 새로운 사람들을 만나면서 실용적인 기술을 배우기에 아주 좋은 방법입니다."]},{"id":"sr-048","level":3,"topic":"역사학과 도심 걷기 투어","voice":"male","sentences":["Our walking tour begins here.","This square was once the town market.","Farmers sold grain and livestock here every Saturday.","The brick building on the corner served as the first town hall.","When the railroad arrived in the eighteen fifties, the town grew rapidly toward the river.","Many of the warehouses you'll see later have since been turned into apartments and restaurants.","As we walk, try to notice how the width of the streets changes, because it tells us which neighborhoods were planned and which grew naturally."],"translations":["걷기 투어는 여기서 시작합니다.","이 광장은 한때 마을 시장이었습니다.","농부들은 매주 토요일 이곳에서 곡물과 가축을 팔았습니다.","모퉁이의 벽돌 건물은 최초의 시청으로 쓰였습니다.","1850년대에 철도가 들어오자 도시는 강 쪽으로 빠르게 성장했습니다.","나중에 보게 될 창고 중 다수는 이후 아파트와 식당으로 바뀌었습니다.","걸으면서 길의 폭이 어떻게 달라지는지 눈여겨보세요. 어느 동네가 계획되었고 어느 동네가 자연스럽게 생겨났는지 알려 주기 때문입니다."]},{"id":"sr-049","level":4,"topic":"메이커스페이스 안전 교육","voice":"female","sentences":["Before anyone touches the equipment, let's review safety.","Safety glasses are required beyond this point.","The laser cutters must never be left running unattended.","Certain plastics release toxic fumes when cut, so check the approved materials list first.","Our 3D printers can run overnight, but only after a staff member has inspected the first few layers.","Anyone who wants to use the woodworking tools must first complete a separate hands-on training session.","If something goes wrong, press the red emergency button on the wall, which cuts power to every machine in the room at once."],"translations":["누구든 장비를 만지기 전에 안전 수칙을 검토합시다.","이 지점부터는 보안경 착용이 필수입니다.","레이저 절단기는 절대로 지켜보는 사람 없이 작동시켜 두면 안 됩니다.","일부 플라스틱은 자를 때 유독 가스를 내므로 먼저 승인된 재료 목록을 확인하세요.","3D 프린터는 밤새 돌릴 수 있지만, 직원이 처음 몇 층을 점검한 뒤에만 가능합니다.","목공 도구를 쓰려는 사람은 먼저 별도의 실습 교육을 이수해야 합니다.","문제가 생기면 벽에 있는 빨간 비상 버튼을 누르세요. 방 안 모든 기계의 전원이 한꺼번에 차단됩니다."]},{"id":"sr-050","level":4,"topic":"조류 행동 연구 현장 안내","voice":"male","sentences":["Welcome to the field station.","Please keep your voices low from here on.","The birds we study are extremely sensitive to human presence.","Researchers observe them from that wooden blind using high-powered binoculars.","Several adults have been fitted with lightweight tracking devices that record their daily movements.","So far, the data suggest that pairs return to almost exactly the same nesting site every spring.","What we're trying to determine now is whether rising temperatures are shifting the timing of their migration earlier each year."],"translations":["현장 연구소에 오신 것을 환영합니다.","여기서부터는 목소리를 낮춰 주세요.","우리가 연구하는 새들은 사람의 존재에 매우 민감합니다.","연구자들은 저 나무 은신처에서 고배율 쌍안경으로 새들을 관찰합니다.","성체 몇 마리에는 일상적인 이동을 기록하는 가벼운 추적 장치를 달았습니다.","지금까지의 자료는 쌍들이 매년 봄 거의 정확히 같은 둥지 자리로 돌아온다는 것을 보여 줍니다.","지금 밝히려는 것은 기온 상승이 해마다 이들의 이동 시기를 앞당기고 있는지 여부입니다."]},{"id":"sr-051","level":4,"topic":"의대 시뮬레이션 센터 견학","voice":"female","sentences":["This is our clinical simulation center.","It looks like a real hospital ward.","The patients, however, are computer-controlled mannequins.","They can breathe, speak, and even show changes in heart rate and blood pressure.","Instructors watch from behind that mirror and adjust the patient's condition in real time.","This allows nursing and medical students to practice handling emergencies without putting anyone at risk.","After each scenario, the team watches a recording of their performance and discusses what they could have done differently."],"translations":["여기가 임상 시뮬레이션 센터입니다.","실제 병동처럼 보입니다.","하지만 환자는 컴퓨터로 제어되는 마네킹입니다.","숨을 쉬고 말을 하며 심박수와 혈압 변화까지 보여 줄 수 있습니다.","강사들은 저 거울 뒤에서 지켜보며 환자의 상태를 실시간으로 조절합니다.","덕분에 간호학과 의학 전공생들이 누구도 위험하게 하지 않고 응급 상황 대처를 연습할 수 있습니다.","각 시나리오가 끝나면 팀은 자신들의 수행을 녹화한 영상을 보고 무엇을 다르게 할 수 있었는지 토론합니다."]},{"id":"sr-052","level":4,"topic":"기록보관소 디지털화 프로젝트","voice":"male","sentences":["Let me show you our digitization project.","These boxes contain letters from early students.","Some of the paper is so fragile it can crack if handled carelessly.","Each page is photographed under carefully controlled lighting to avoid fading the ink.","Volunteers then transcribe the handwriting so the text can be searched by keyword online.","Older handwriting styles can be surprisingly difficult to read, even for people who have done this for years.","Once the collection is complete, historians anywhere in the world will be able to study these documents without ever visiting the campus."],"translations":["우리의 디지털화 프로젝트를 보여 드리겠습니다.","이 상자들에는 초기 학생들의 편지가 들어 있습니다.","일부 종이는 너무 약해서 부주의하게 다루면 갈라질 수 있습니다.","잉크가 바래지 않도록 각 쪽을 세심하게 조절한 조명 아래에서 촬영합니다.","그다음 자원봉사자들이 손글씨를 옮겨 적어 온라인에서 키워드로 검색할 수 있게 합니다.","오래된 필체는 이 일을 몇 년 해 온 사람에게도 의외로 읽기 어려울 수 있습니다.","자료가 완성되면 전 세계 어디서든 역사학자들이 캠퍼스를 방문하지 않고도 이 문서들을 연구할 수 있게 됩니다."]},{"id":"sr-053","level":4,"topic":"화석 처리 실험실 견학","voice":"female","sentences":["This is the fossil preparation lab.","Most fossils arrive still encased in rock.","Our job is to remove that rock without damaging the bone.","For delicate areas, preparators use tiny air-powered tools under a microscope.","A single vertebra from a large dinosaur can take several weeks of careful work to expose.","Through this window, visitors can watch the process and ask the preparators questions about their work.","The specimen on the main table was discovered by a graduate student last summer and may turn out to be a previously unknown species."],"translations":["여기가 화석 처리 실험실입니다.","대부분의 화석은 아직 암석에 싸인 채로 도착합니다.","우리 일은 뼈를 손상하지 않고 그 암석을 제거하는 것입니다.","섬세한 부분에는 처리 담당자가 현미경 아래에서 공기압으로 작동하는 작은 도구를 씁니다.","큰 공룡의 척추뼈 하나를 드러내는 데 몇 주의 세심한 작업이 걸리기도 합니다.","방문객은 이 창을 통해 작업 과정을 지켜보고 처리 담당자에게 작업에 관해 질문할 수 있습니다.","중앙 테이블의 표본은 지난여름 한 대학원생이 발견한 것으로, 이전에 알려지지 않은 종으로 밝혀질 수도 있습니다."]},{"id":"sr-054","level":4,"topic":"풍력 에너지 연구 시설","voice":"male","sentences":["Welcome to the wind energy test facility.","That tunnel generates winds of controlled speed.","We use it to test scaled-down models of turbine blades.","Small changes in a blade's curve can significantly affect how much power it produces.","Sensors along each blade measure vibration, since excessive vibration shortens a turbine's lifespan.","One current project is examining whether blade designs inspired by whale fins can reduce noise.","Noise is actually one of the main reasons communities object to wind farms, so solving it could make new projects far easier to approve."],"translations":["풍력 에너지 시험 시설에 오신 것을 환영합니다.","저 터널은 속도를 조절한 바람을 만들어 냅니다.","그것으로 터빈 날개의 축소 모형을 시험합니다.","날개 곡선의 작은 변화가 발전량에 상당한 영향을 줄 수 있습니다.","과도한 진동은 터빈 수명을 줄이므로 각 날개를 따라 설치된 센서가 진동을 측정합니다.","현재 한 프로젝트는 고래 지느러미에서 영감을 얻은 날개 설계가 소음을 줄일 수 있는지 살펴보고 있습니다.","소음은 사실 지역 사회가 풍력 단지에 반대하는 주된 이유 중 하나이므로, 이를 해결하면 새 사업의 승인이 훨씬 쉬워질 수 있습니다."]},{"id":"sr-055","level":5,"topic":"인간 대상 연구 윤리 교육","voice":"female","sentences":["Informed consent is the foundation of ethical research.","Participants must understand exactly what they are agreeing to.","Consent forms should therefore avoid technical jargon wherever possible.","Participants are entitled to withdraw at any point without having to justify their decision.","Any study involving minors or other vulnerable groups requires an additional layer of review by the board.","Data must be stored in an anonymized form, and identifying information should be kept separately under restricted access.","Bear in mind that even seemingly harmless questions can cause distress, so you should be prepared to refer participants to support services if necessary."],"translations":["충분한 설명에 근거한 동의는 윤리적 연구의 토대입니다.","참가자는 자신이 무엇에 동의하는지 정확히 이해해야 합니다.","따라서 동의서는 가능한 한 전문 용어를 피해야 합니다.","참가자는 결정의 이유를 밝힐 필요 없이 언제든 참여를 철회할 권리가 있습니다.","미성년자나 다른 취약 집단이 관련된 연구는 위원회의 추가 심사를 거쳐야 합니다.","자료는 익명화된 형태로 저장해야 하며, 신원을 알 수 있는 정보는 접근을 제한해 따로 보관해야 합니다.","겉보기에 무해한 질문도 고통을 줄 수 있음을 명심하고, 필요하면 참가자를 지원 서비스로 안내할 준비를 해 두어야 합니다."]},{"id":"sr-056","level":5,"topic":"입자 물리 실험 시설 견학","voice":"male","sentences":["You are now standing above the detector.","It sits roughly thirty meters beneath our feet.","The surrounding rock shields it from most cosmic radiation.","Particles collide at nearly the speed of light, producing showers of short-lived fragments.","The detector records millions of these events every second, far more than could ever be stored.","Sophisticated algorithms therefore decide almost instantaneously which collisions are worth keeping for further analysis.","Ironically, the most significant discoveries often emerge not from dramatic signals but from tiny statistical deviations that accumulate over years of painstaking observation."],"translations":["여러분은 지금 검출기 바로 위에 서 있습니다.","그것은 우리 발아래 약 30미터 지점에 있습니다.","주변 암반이 대부분의 우주 방사선으로부터 검출기를 차단해 줍니다.","입자들이 거의 빛의 속도로 충돌해 수명이 짧은 파편들을 쏟아 냅니다.","검출기는 매초 이런 사건을 수백만 건 기록하는데, 이는 저장할 수 있는 양을 훨씬 넘어섭니다.","그래서 정교한 알고리즘이 어떤 충돌을 추가 분석을 위해 남길지 거의 즉시 결정합니다.","역설적으로 가장 중요한 발견은 극적인 신호가 아니라 수년간의 고된 관측 끝에 쌓인 미세한 통계적 편차에서 나오는 경우가 많습니다."]},{"id":"sr-057","level":5,"topic":"유전체 분석 센터 브리핑","voice":"female","sentences":["This facility sequences thousands of genomes annually.","Contamination is our single greatest concern.","Even a trace of foreign DNA can invalidate an entire batch of samples.","For that reason, sample preparation and analysis take place in physically separate rooms.","Air pressure in the clean room is kept slightly higher than in the corridor to keep particles out.","The sequencers themselves are remarkably fast, but interpreting the resulting data remains the real bottleneck.","Distinguishing a genuinely harmful mutation from harmless natural variation requires not only computational power but also careful judgment informed by clinical evidence."],"translations":["이 시설은 해마다 수천 개의 유전체를 해독합니다.","오염이 우리의 가장 큰 걱정거리입니다.","외부 DNA가 극미량만 있어도 시료 한 묶음 전체가 무효가 될 수 있습니다.","그런 이유로 시료 준비와 분석은 물리적으로 분리된 방에서 이루어집니다.","입자가 들어오지 않도록 청정실의 기압은 복도보다 약간 높게 유지됩니다.","해독 장비 자체는 놀라울 만큼 빠르지만, 그 결과 자료를 해석하는 일이 여전히 진짜 병목입니다.","실제로 해로운 돌연변이를 무해한 자연 변이와 구별하려면 계산 능력뿐 아니라 임상 증거에 바탕을 둔 신중한 판단도 필요합니다."]},{"id":"sr-058","level":5,"topic":"고문서 보존 처리실","voice":"male","sentences":["Conservation is fundamentally about restraint.","Our aim is to stabilize objects, not to make them look new.","Every intervention we make must be reversible by future conservators.","This manuscript, for instance, suffered water damage during a flood in the nineteenth century.","Rather than replacing the missing fragments, we've reinforced the edges with thin Japanese tissue and a wheat starch paste.","Those materials were chosen precisely because they can be removed with moisture, leaving the original paper unharmed.","Some earlier restorations, by contrast, relied on adhesives that have since yellowed and become brittle, and undoing that well-intentioned damage now accounts for much of our work."],"translations":["보존 처리는 근본적으로 절제에 관한 일입니다.","우리의 목표는 물건을 새것처럼 보이게 하는 것이 아니라 안정시키는 것입니다.","우리가 하는 모든 처리는 미래의 보존가가 되돌릴 수 있어야 합니다.","예를 들어 이 필사본은 19세기의 홍수 때 물에 손상되었습니다.","떨어져 나간 조각을 대체하는 대신 얇은 일본 화지와 밀 전분 풀로 가장자리를 보강했습니다.","그 재료들은 바로 습기로 제거할 수 있어 원래 종이를 손상하지 않기 때문에 선택되었습니다.","반면 일부 이전 복원은 그 후 누렇게 변하고 부서지기 쉬워진 접착제에 의존했으며, 그 선의의 손상을 되돌리는 일이 지금 우리 작업의 상당 부분을 차지합니다."]},{"id":"sr-059","level":5,"topic":"수중 고고학 잠수 브리핑","voice":"female","sentences":["Today's dive targets the eastern section of the wreck.","Visibility is expected to be poor this morning.","Each team must remain within arm's reach of its partner at all times.","Nothing is to be lifted from the seabed until its position has been photographed and recorded.","An artifact removed from its context loses much of its value as evidence, however impressive it may look.","Wooden objects in particular must be kept submerged in fresh water until they reach the lab, or they'll warp as they dry.","Should anyone experience equipment trouble or disorientation, signal your partner immediately and ascend slowly together, regardless of how much work remains unfinished."],"translations":["오늘 잠수는 난파선 동쪽 구역을 대상으로 합니다.","오늘 아침에는 시야가 나쁠 것으로 예상됩니다.","각 팀은 항상 짝과 팔이 닿는 거리 안에 있어야 합니다.","해저의 어떤 물건도 위치를 촬영하고 기록하기 전에는 들어 올려서는 안 됩니다.","맥락에서 떨어져 나온 유물은 겉보기에 아무리 인상적이어도 증거로서의 가치를 상당 부분 잃습니다.","특히 나무 유물은 실험실에 도착할 때까지 민물에 담가 두어야 하며, 그렇지 않으면 마르면서 뒤틀립니다.","장비 문제나 방향 감각 상실을 겪는다면 남은 작업이 얼마나 되든 즉시 짝에게 신호하고 함께 천천히 상승하세요."]},{"id":"sr-060","level":5,"topic":"학회 발표 준비 워크숍","voice":"male","sentences":["Conference talks are not miniature papers.","Audiences retain remarkably little from a fifteen-minute presentation.","You should therefore build your talk around a single central claim.","Resist the temptation to include every robustness check you conducted during the project.","Those details belong in an appendix or in your answers to questions, not on crowded slides that nobody can read.","When you receive a hostile question, acknowledge its legitimate core before explaining why your conclusion still holds.","Finally, rehearse in front of colleagues outside your specialty, because if they can follow your argument, experts in the audience almost certainly will as well."],"translations":["학회 발표는 축소판 논문이 아닙니다.","청중은 15분 발표에서 놀라울 만큼 적은 것만 기억합니다.","따라서 하나의 핵심 주장을 중심으로 발표를 구성해야 합니다.","프로젝트 중에 실시한 모든 견고성 검증을 넣고 싶은 유혹을 참으세요.","그런 세부 사항은 아무도 읽지 못하는 빽빽한 슬라이드가 아니라 부록이나 질의응답에 들어가야 합니다.","공격적인 질문을 받으면 왜 여전히 결론이 유효한지 설명하기 전에 그 질문의 타당한 핵심을 인정하세요.","마지막으로 전공이 다른 동료들 앞에서 리허설하세요. 그들이 여러분의 논지를 따라갈 수 있다면 청중 속 전문가들도 거의 확실히 따라올 것입니다."]}];
